"crew.subagent_stale_list": async (params: unknown, ctx?: RpcContext) => {
  const p = params as { id?: string; cc_session_id?: string; parent_thread_id?: string };
  if (!p?.parent_thread_id) throw new Error("subagent_stale_list: parent_thread_id is required");
  if (!deps.subagentState) throw new Error("subagent state capability unavailable");
  const agent = targetAgent(p);
  const { ownerUid } = requireSponsor("subagent_stale_list", agent, ctx);
  const edges = await deps.subagentState.list(ownerUid, agent.id, p.parent_thread_id);
