    machine: deps.machine,
    target: agent.id,
    parent_thread_id: p.parent_thread_id,
    owner_uid: ownerUid,
    edges,
    stale_ids: edges.filter((edge) => edge.stale).map((edge) => edge.child_thread_id),
    requested_by: ctx?.source,
  };
},

