test("stop + resume route through the driver; resume never passes a caller uid", async () => {
  const { store, cleanup } = freshStore();
  const { driver, calls } = makeDriver();
  const m = buildMethods({
    store, machine: "patisserie", screenSessions: async () => [],
    orchestrator: driver, spawnUid: "_ephemeral", writers: ["brioche"],
  });
  await m["crew.agent_stop"]({ id: "eng-1" }, VERIFIED);
  const r = (await m["crew.agent_resume"]({ id: "eng-1" }, VERIFIED)) as Record<string, unknown>;
  expect(calls.map((c) => c.method)).toEqual(["stop", "resume"]);
  // uid must come from the tombstone manifest inside the orchestrator, not the RPC
  expect((calls[1].opts as { runAsUid?: string }).runAsUid).toBeUndefined();
  expect(r.resumed).toBe("spawned-1");
  cleanup();
});

test("stop -> resume re-provisions Wire signing key from out-of-band store without logging or tombstoning it", async () => {
  const { store, cleanup } = freshStore();
  const { driver, calls } = makeDriver();
  const keys = new Map<string, string>();
  const audits: Array<Record<string, unknown>> = [];
  const agentKeyStore = {
    remember: async (id: string, key: string) => { keys.set(id, key); },
    read: async (id: string) => keys.get(id),
    forget: async (id: string) => { keys.delete(id); },
  };
  const m = buildMethods({
    store, machine: "patisserie", screenSessions: async () => [],
    orchestrator: driver, spawnUid: "_ephemeral", writers: ["brioche"],
    agentKeyStore, auditLifecycle: (event) => { audits.push(event); },
  });
  await m["crew.agent_spawn"]({
    env: { AGENT_ID: "eng-1", AGENT_PRIVATE_KEY: "test-private-key-never-log" },
  }, VERIFIED);
  await m["crew.agent_stop"]({ id: "eng-1" }, VERIFIED);
  const result = await m["crew.agent_resume"]({ id: "eng-1" }, VERIFIED) as Record<string, unknown>;
  const resume = calls.find((call) => call.method === "resume")!.opts as { env?: Record<string, string> };
  expect(resume.env?.AGENT_PRIVATE_KEY).toBe("test-private-key-never-log");
  expect(result.wire_key_reprovisioned).toBe(true);
  expect(JSON.stringify(result)).not.toContain("test-private-key-never-log");
  expect(JSON.stringify(audits)).not.toContain("test-private-key-never-log");
