/** Stop (hard-kill + tombstone) an agent on THIS machine. */
"crew.agent_stop": async (params: unknown, ctx?: RpcContext) => {
  requireVerifiedWriter("agent_stop", ctx);
  const orch = requireOrchestrator();
  const p = params as { id?: string };
  if (!p?.id) throw new Error("agent_stop: id is required");
  // AGI-83: this is the fleet's only kill path with no automatic log — an
  // unaudited hard kill is unattributable by construction, so the audit
  // fires on the FAILURE path too (a thrown stop may still have side
  // effects worth attributing).
  const startedAt = Date.now();
  const event: Record<string, unknown> = {
    event: "crew.lifecycle.agent_stopped",
    machine: deps.machine,
    target: p.id,
    requested_by: ctx?.source,
    hard_kill: true,
  };
  try {
    await orch.stopAgent(p.id);
  } catch (err) {
    event.outcome = "error";
    event.error = err instanceof Error ? err.message : String(err);
    event.elapsed_ms = Date.now() - startedAt;
    await deps.auditLifecycle?.(event);
    throw err;
  }
  event.outcome = "stopped";
  event.elapsed_ms = Date.now() - startedAt;
  await deps.auditLifecycle?.(event);
  return { ...event, stopped: p.id };
},

