test("agent_stop audits the kill with requested_by — success path", async () => {
  const { store, cleanup } = freshStore();
  const { driver } = makeDriver();
  const audits: Array<Record<string, unknown>> = [];
  const m = buildMethods({
    store, machine: "patisserie", screenSessions: async () => [],
    orchestrator: driver, spawnUid: "_ephemeral", writers: ["brioche"],
    auditLifecycle: (event) => { audits.push(event); },
  });
  const r = (await m["crew.agent_stop"]({ id: "eng-1" }, VERIFIED)) as Record<string, unknown>;
  expect(audits).toHaveLength(1);
  expect(audits[0].event).toBe("crew.lifecycle.agent_stopped");
  expect(audits[0].target).toBe("eng-1");
  expect(audits[0].requested_by).toBe("brioche");
  expect(audits[0].outcome).toBe("stopped");
  // return shape keeps its pre-audit keys for existing callers
  expect(r.stopped).toBe("eng-1");
  expect(r.machine).toBe("patisserie");
  expect(r.requested_by).toBe("brioche");
  cleanup();
});

test("agent_stop audits the kill even when the stop throws, then rethrows", async () => {
  const { store, cleanup } = freshStore();
  const { driver } = makeDriver();
  driver.stopAgent = async () => { throw new Error("screen already gone"); };
  const audits: Array<Record<string, unknown>> = [];
  const m = buildMethods({
    store, machine: "patisserie", screenSessions: async () => [],
    orchestrator: driver, spawnUid: "_ephemeral", writers: ["brioche"],
    auditLifecycle: (event) => { audits.push(event); },
  });
  await expect(m["crew.agent_stop"]({ id: "eng-1" }, VERIFIED)).rejects.toThrow(/screen already gone/);
  expect(audits).toHaveLength(1);
  expect(audits[0].outcome).toBe("error");
  expect(audits[0].error).toMatch(/screen already gone/);
  expect(audits[0].requested_by).toBe("brioche");
  cleanup();
});

